				// Current HP is HPY, which is >= 1, so we're fine
				// Cost: addATK * a + addDEF * d
				cost := addATK*a + addDEF*d
				if cost < minCost {
					minCost = cost
				}
				continue
			}

			// Yang needs HP > tKill * dmgToYang
			// So required HP = tKill * dmgToYang + 1
			requiredHP := tKill*dmgToYang + 1

			if requiredHP <= HPY {
				// Current HP is enough
				cost := addATK*a + addDEF*d
				if cost < minCost {
